import React, { useState, useEffect, useRef } from 'react';
import {
  View,
  StyleSheet,
  ScrollView,
  RefreshControl,
  Dimensions,
  Alert,
} from 'react-native';
import {
  Card,
  Title,
  Text,
  Button,
  Chip,
  useTheme,
  ProgressBar,
  Divider,
} from 'react-native-paper';
import { Ionicons } from '@expo/vector-icons';
import { LineChart } from 'react-native-chart-kit';
import { coldChainAPI } from '../services/api';

const { width } = Dimensions.get('window');

const ColdChainScreen = () => {
  const [coldChainData, setColdChainData] = useState([]);
  const [currentBatch, setCurrentBatch] = useState('BATCH001');
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [mlPrediction, setMlPrediction] = useState(null);
  const [isPredicting, setIsPredicting] = useState(false);
  const [chartData, setChartData] = useState({
    labels: [],
    datasets: [
      {
        data: [],
        color: (opacity = 1) => `rgba(59, 130, 246, ${opacity})`,
        strokeWidth: 2,
      },
      {
        data: [],
        color: (opacity = 1) => `rgba(16, 185, 129, ${opacity})`,
        strokeWidth: 2,
      },
    ],
  });
  
  const theme = useTheme();
  const intervalRef = useRef(null);

  useEffect(() => {
    loadColdChainData();
    startRealTimeUpdates();
    
    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, []);

  const loadColdChainData = async () => {
    try {
      // Mock data - replace with actual API call
      const mockData = [
        {
          batchID: 'BATCH001',
          temperature: 4.2,
          humidity: 45.3,
          timestamp: new Date(Date.now() - 300000).toISOString(),
        },
        {
          batchID: 'BATCH001',
          temperature: 4.5,
          humidity: 46.1,
          timestamp: new Date(Date.now() - 240000).toISOString(),
        },
        {
          batchID: 'BATCH001',
          temperature: 4.8,
          humidity: 47.2,
          timestamp: new Date(Date.now() - 180000).toISOString(),
        },
        {
          batchID: 'BATCH001',
          temperature: 5.1,
          humidity: 48.5,
          timestamp: new Date(Date.now() - 120000).toISOString(),
        },
        {
          batchID: 'BATCH001',
          temperature: 5.5,
          humidity: 49.8,
          timestamp: new Date(Date.now() - 60000).toISOString(),
        },
        {
          batchID: 'BATCH001',
          temperature: 5.8,
          humidity: 50.2,
          timestamp: new Date().toISOString(),
        },
      ];
      
      setColdChainData(mockData);
      updateChartData(mockData);
    } catch (error) {
      console.error('Error loading cold chain data:', error);
    }
  };

  const startRealTimeUpdates = () => {
    intervalRef.current = setInterval(() => {
      // Simulate real-time IoT sensor data
      const newDataPoint = {
        batchID: currentBatch,
        temperature: 4.0 + Math.random() * 4, // 4-8°C range
        humidity: 40 + Math.random() * 20, // 40-60% range
        timestamp: new Date().toISOString(),
      };
      
      setColdChainData(prev => {
        const updated = [...prev, newDataPoint];
        if (updated.length > 20) {
          updated.shift(); // Keep only last 20 data points
        }
        updateChartData(updated);
        return updated;
      });
    }, 3000); // Update every 3 seconds
  };

  const updateChartData = (data) => {
    const labels = data.map((_, index) => `${index + 1}`);
    const temperatures = data.map(d => d.temperature);
    const humidities = data.map(d => d.humidity);
    
    setChartData({
      labels,
      datasets: [
        {
          data: temperatures,
          color: (opacity = 1) => `rgba(239, 68, 68, ${opacity})`, // Red for temperature
          strokeWidth: 2,
        },
        {
          data: humidities,
          color: (opacity = 1) => `rgba(59, 130, 246, ${opacity})`, // Blue for humidity
          strokeWidth: 2,
        },
      ],
    });
  };

  const onRefresh = async () => {
    setIsRefreshing(true);
    await loadColdChainData();
    setIsRefreshing(false);
  };

  const getCurrentStatus = () => {
    if (coldChainData.length === 0) return 'UNKNOWN';
    
    const latest = coldChainData[coldChainData.length - 1];
    const temp = latest.temperature;
    const humidity = latest.humidity;
    
    if (temp < 2 || temp > 8 || humidity < 30 || humidity > 70) {
      return 'CRITICAL';
    } else if (temp < 3 || temp > 7 || humidity < 35 || humidity > 65) {
      return 'WARNING';
    } else {
      return 'SAFE';
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'SAFE':
        return 'green';
      case 'WARNING':
        return 'orange';
      case 'CRITICAL':
        return 'red';
      default:
        return 'gray';
    }
  };

  const getStatusIcon = (status) => {
    switch (status) {
      case 'SAFE':
        return 'checkmark-circle';
      case 'WARNING':
        return 'warning';
      case 'CRITICAL':
        return 'alert-circle';
      default:
        return 'help-circle';
    }
  };

  const predictRisk = async () => {
    if (coldChainData.length === 0) {
      Alert.alert('Error', 'No data available for prediction');
      return;
    }

    setIsPredicting(true);
    
    try {
      const latestData = coldChainData[coldChainData.length - 1];
      const predictionData = {
        temperature: latestData.temperature,
        humidity: latestData.humidity,
        batchID: latestData.batchID,
      };

      // Mock ML prediction - replace with actual API call
      setTimeout(() => {
        const mockPrediction = {
          risk_level: Math.random() > 0.5 ? 'Safe' : 'Spoiled',
          confidence: (0.7 + Math.random() * 0.3).toFixed(2), // 70-100% confidence
          temperature_risk: latestData.temperature < 3 || latestData.temperature > 7 ? 'High' : 'Low',
          humidity_risk: latestData.humidity < 35 || latestData.humidity > 65 ? 'High' : 'Low',
          recommendation: Math.random() > 0.5 ? 'Continue monitoring' : 'Immediate action required',
        };
        
        setMlPrediction(mockPrediction);
        setIsPredicting(false);
      }, 2000);
      
    } catch (error) {
      Alert.alert('Error', 'Failed to get ML prediction');
      setIsPredicting(false);
    }
  };

  const getCurrentMetrics = () => {
    if (coldChainData.length === 0) return { temperature: 0, humidity: 0 };
    
    const latest = coldChainData[coldChainData.length - 1];
    return {
      temperature: latest.temperature,
      humidity: latest.humidity,
    };
  };

  const styles = StyleSheet.create({
    container: {
      flex: 1,
      backgroundColor: theme.colors.background,
    },
    header: {
      padding: 20,
      paddingTop: 40,
      backgroundColor: theme.colors.primary,
    },
    headerTitle: {
      color: 'white',
      fontSize: 24,
      fontWeight: 'bold',
      marginBottom: 5,
    },
    headerSubtitle: {
      color: 'white',
      fontSize: 16,
      opacity: 0.9,
    },
    content: {
      padding: 20,
    },
    sectionTitle: {
      fontSize: 20,
      fontWeight: 'bold',
      marginBottom: 15,
      color: theme.colors.onSurface,
    },
    statusCard: {
      marginBottom: 20,
      borderLeftWidth: 4,
      borderLeftColor: getStatusColor(getCurrentStatus()),
    },
    statusHeader: {
      flexDirection: 'row',
      justifyContent: 'space-between',
      alignItems: 'center',
      marginBottom: 15,
    },
    statusContainer: {
      flexDirection: 'row',
      alignItems: 'center',
    },
    metricsGrid: {
      flexDirection: 'row',
      justifyContent: 'space-between',
      marginBottom: 20,
    },
    metricCard: {
      width: '48%',
      alignItems: 'center',
    },
    metricValue: {
      fontSize: 24,
      fontWeight: 'bold',
      color: theme.colors.primary,
    },
    metricLabel: {
      fontSize: 12,
      color: theme.colors.onSurface,
      opacity: 0.7,
      textAlign: 'center',
    },
    chartCard: {
      marginBottom: 20,
    },
    chartTitle: {
      marginBottom: 15,
      textAlign: 'center',
    },
    predictionCard: {
      marginBottom: 20,
    },
    predictionHeader: {
      flexDirection: 'row',
      justifyContent: 'space-between',
      alignItems: 'center',
      marginBottom: 15,
    },
    predictionResult: {
      alignItems: 'center',
      marginVertical: 15,
    },
    predictionValue: {
      fontSize: 28,
      fontWeight: 'bold',
      marginBottom: 5,
    },
    predictionConfidence: {
      fontSize: 16,
      opacity: 0.7,
    },
    riskIndicators: {
      flexDirection: 'row',
      justifyContent: 'space-around',
      marginTop: 15,
    },
    riskIndicator: {
      alignItems: 'center',
    },
    riskLabel: {
      fontSize: 12,
      marginBottom: 5,
    },
    riskValue: {
      fontSize: 16,
      fontWeight: 'bold',
    },
    recommendation: {
      marginTop: 15,
      padding: 15,
      backgroundColor: theme.colors.surfaceVariant,
      borderRadius: 8,
    },
    recommendationText: {
      textAlign: 'center',
      fontStyle: 'italic',
    },
  });

  const currentMetrics = getCurrentMetrics();
  const currentStatus = getCurrentStatus();

  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <Text style={styles.headerTitle}>Cold Chain Monitoring</Text>
        <Text style={styles.headerSubtitle}>Real-time Temperature & Humidity Tracking</Text>
      </View>

      <ScrollView
        style={styles.content}
        refreshControl={
          <RefreshControl refreshing={isRefreshing} onRefresh={onRefresh} />
        }
      >
        {/* Current Status */}
        <Card style={styles.statusCard}>
          <Card.Content>
            <View style={styles.statusHeader}>
              <Title>Current Status</Title>
              <View style={styles.statusContainer}>
                <Ionicons
                  name={getStatusIcon(currentStatus)}
                  size={24}
                  color={getStatusColor(currentStatus)}
                  style={{ marginRight: 8 }}
                />
                <Chip
                  mode="outlined"
                  textStyle={{ color: getStatusColor(currentStatus) }}
                  style={{ borderColor: getStatusColor(currentStatus) }}
                >
                  {currentStatus}
                </Chip>
              </View>
            </View>
            
            <View style={styles.metricsGrid}>
              <View style={styles.metricCard}>
                <Text style={styles.metricValue}>{currentMetrics.temperature.toFixed(1)}°C</Text>
                <Text style={styles.metricLabel}>Temperature</Text>
              </View>
              <View style={styles.metricCard}>
                <Text style={styles.metricValue}>{currentMetrics.humidity.toFixed(1)}%</Text>
                <Text style={styles.metricLabel}>Humidity</Text>
              </View>
            </View>
          </Card.Content>
        </Card>

        {/* Live Chart */}
        <Card style={styles.chartCard}>
          <Card.Content>
            <Title style={styles.chartTitle}>Live Temperature & Humidity</Title>
            <LineChart
              data={chartData}
              width={width - 80}
              height={220}
              chartConfig={{
                backgroundColor: theme.colors.surface,
                backgroundGradientFrom: theme.colors.surface,
                backgroundGradientTo: theme.colors.surface,
                decimalPlaces: 1,
                color: (opacity = 1) => `rgba(0, 0, 0, ${opacity})`,
                labelColor: (opacity = 1) => `rgba(0, 0, 0, ${opacity})`,
                style: {
                  borderRadius: 16,
                },
                propsForDots: {
                  r: '4',
                  strokeWidth: '2',
                },
              }}
              bezier
              style={{
                marginVertical: 8,
                borderRadius: 16,
              }}
              legend={['Temperature (°C)', 'Humidity (%)']}
            />
          </Card.Content>
        </Card>

        {/* ML Risk Prediction */}
        <Card style={styles.predictionCard}>
          <Card.Content>
            <View style={styles.predictionHeader}>
              <Title>AI Risk Assessment</Title>
              <Button
                mode="contained"
                onPress={predictRisk}
                loading={isPredicting}
                disabled={isPredicting}
              >
                {isPredicting ? 'Analyzing...' : 'Predict Risk'}
              </Button>
            </View>

            {mlPrediction && (
              <>
                <View style={styles.predictionResult}>
                  <Text style={[
                    styles.predictionValue,
                    { color: mlPrediction.risk_level === 'Safe' ? 'green' : 'red' }
                  ]}>
                    {mlPrediction.risk_level}
                  </Text>
                  <Text style={styles.predictionConfidence}>
                    Confidence: {(mlPrediction.confidence * 100).toFixed(0)}%
                  </Text>
                </View>

                <View style={styles.riskIndicators}>
                  <View style={styles.riskIndicator}>
                    <Text style={styles.riskLabel}>Temperature Risk</Text>
                    <Chip
                      mode="outlined"
                      textStyle={{ 
                        color: mlPrediction.temperature_risk === 'High' ? 'red' : 'green' 
                      }}
                      style={{ 
                        borderColor: mlPrediction.temperature_risk === 'High' ? 'red' : 'green' 
                      }}
                    >
                      {mlPrediction.temperature_risk}
                    </Chip>
                  </View>
                  <View style={styles.riskIndicator}>
                    <Text style={styles.riskLabel}>Humidity Risk</Text>
                    <Chip
                      mode="outlined"
                      textStyle={{ 
                        color: mlPrediction.humidity_risk === 'High' ? 'red' : 'green' 
                      }}
                      style={{ 
                        borderColor: mlPrediction.humidity_risk === 'High' ? 'red' : 'green' 
                      }}
                    >
                      {mlPrediction.humidity_risk}
                    </Chip>
                  </View>
                </View>

                <View style={styles.recommendation}>
                  <Text style={styles.recommendationText}>
                    <Text style={{ fontWeight: 'bold' }}>Recommendation:</Text> {mlPrediction.recommendation}
                  </Text>
                </View>
              </>
            )}
          </Card.Content>
        </Card>

        {/* Batch Information */}
        <Card>
          <Card.Content>
            <Title>Monitoring Batch: {currentBatch}</Title>
            <Text style={{ marginBottom: 10 }}>
              Real-time IoT sensor data updates every 3 seconds
            </Text>
            <Divider style={{ marginVertical: 10 }} />
            <Text style={{ fontSize: 12, opacity: 0.7 }}>
              Safe Range: Temperature 2-8°C, Humidity 30-70%
            </Text>
          </Card.Content>
        </Card>
      </ScrollView>
    </View>
  );
};

export default ColdChainScreen;
